  function renderReviewChecklist(){var list=$('#review-checklist');if(!list)return [];var checks=reviewChecks(),errors=checks.filter(function(check){return check.status==='error'}),warnings=checks.filter(function(check){return check.status==='warning'}),ready=checks.filter(function(check){return check.status==='ok'}).length,card=$('.review-card'),payment=$('.payment-card');list.innerHTML=checks.map(function(check){var icon=check.status==='ok'?'✓':check.status==='warning'?'!':'×',arrow=check.status==='ok'?'':'→';return '<button type="button" class="review-check is-'+check.status+'" data-review-step="'+check.step+'"><i>'+icon+'</i><span><strong>'+safe(check.title)+'</strong><small>'+safe(check.text)+'</small></span><em>'+arrow+'</em></button>'}).join('');$('#review-check-count').textContent=ready+' из '+checks.length;card.classList.toggle('has-errors',!!errors.length);card.classList.toggle('has-warnings',!errors.length&&!!warnings.length);card.classList.toggle('is-ready',!errors.length&&!warnings.length);payment.classList.toggle('is-locked',!!errors.length);syncFinalCta(errors);if(errors.length){$('#review-status-icon').textContent='!';$('#review-status-title').textContent='Нужно исправить '+errors.length+' '+(errors.length===1?'пункт':'пункта');$('#review-status-copy').textContent='Нажмите на проблему — мы сразу вернём вас в нужный раздел.'}else if(warnings.length){$('#review-status-icon').textContent='✓';$('#review-status-title').textContent='Приглашение готово к публикации';$('#review-status-copy').textContent='Критичных ошибок нет. Остались только рекомендации, которые можно пропустить.'}else{$('#review-status-icon').textContent='✓';$('#review-status-title').textContent='Всё готово к публикации';$('#review-status-copy').textContent='Обязательные данные и включённые разделы заполнены.'}return errors}
